from taf.internal.ue.pioneer.api.facade import Pioneer
from taf.internal.aliasing import aliasing_scope


class api(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, store = aliasing_scope(lookup_arg='service',
                                           lookup_type=Pioneer)

    def setup_service(self, host, port=None, alias=None):
        """
        connect to the pioneer service and create alias-instance mapping

        :param str host: ip address of control pc which the pioneer service running on
        :param Optional[int] port: pioneer service listening port, 30999 by default
        :param Optional[str] alias: pioneer service alias
        """
        port = int(port) if port else None
        pioneer = Pioneer(host, port)
        pioneer.setup()
        self.store.add(pioneer, alias)
        return pioneer

    @lookup_handler.implicit_lookup
    def teardown_service(self, service=None):
        """
        disconnect from pioneer service and clear resources

        :param Optional[Union[str, Pioneer]] service: pioneer service name or instance
        """
        service.teardown()

    @lookup_handler.implicit_lookup
    def getmoduleslotinfo(self, until_timeout=None, service=None):
        """
        execute GetModuleSlotInfo command to detect all the UEs connected

        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, Pioneer]] service: pioneer service name or instance
        :return: dict
        e.g.
        {
            "CMD": "GetModuleSlotInfo",
            "Param": {
                   "State": 0, # return 0 if success, otherwise return the error codes
                   "ModuleSlots": [1,2,3,4,5,6,7,8]
                   "ModuleStatus":[1,0,1,1,1,0,1,1]
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return service.GetModuleSlotInfo(until_timeout=until_timeout).dictionary

