    @lookup_handler.implicit_lookup
    def starttraffic(self, eqindex, protocol, address, port, testtime, bandwidth, buffersize, packetsize,
                     iperftype, direction, threadcount,
                     until_timeout=None, service=None):
        """
        execute StartTraffic to start Link Traffic

        :param Union[int, list] eqindex: UE index or UE index list.
        :param str protocol: traffic protocol, e.g. 'UDP', others.
        :param str address: target(e.g. app server) ip address
        :param str port: target port NO.
        :param str testtime: time last for traffic in second.
        :param int bandwidth: bandwidth in Kbps
        :param int buffersize: buffersize in KB
        :param int packetsize: packetsize in Byte
        :param int iperftype: iperf type, e.g 0: iperf2 1:iperf3.
        :param int direction: traffic direction, e.g 0: UpLink 1: DownLink.
        :param int threadcount: tread count.
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, Pioneer]] service: pioneer service name or instance
        :return: dict
        {
            "CMD": "StartTraffic",
            "EQIndex": -1, # UNION[int, list] {-1,1~n} or [1, 2,3...],
                           # -1 means all UEs, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
                 "SubStates": [0, 0, 0...]   # if EQIndex is -1, return all UE’s result.
                                             # return 0 if success, otherwise return the error codes.
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        eqindex = [int(index) for index in eqindex] if isinstance(eqindex, list) else int(eqindex)
        port = str(port)
        testtime = str(testtime)
        bandwidth = int(bandwidth)
        buffersize = int(buffersize)
        packetsize = int(packetsize)
        iperftype = int(iperftype)
        direction = int(direction)
        threadcount = int(threadcount)
        return service.StartTraffic(eqindex, protocol, address, port, testtime, bandwidth, buffersize, packetsize,
                                    iperftype, direction, threadcount, until_timeout=until_timeout).dictionary

    @lookup_handler.implicit_lookup
    def startultraffic(self, eqindex, protocol, address, port, testtime, bandwidth, buffersize, packetsize,
                       until_timeout=None, service=None):
        """
        execute StartULtraffic to start Up Link Traffic

        :param int eqindex: UE index, -1 means all UEs, starts from 1 for single specific UE
        :param str protocol: traffic protocol, e.g. 'UDP', others???
        :param str address: target(e.g. app server) ip address
        :param int port: target port NO.
        :param int testtime: time last for traffic in second???
        :param int bandwidth: bandwidth in Kbps
        :param int buffersize: buffersize in KB
        :param int packetsize: packetsize in Byte
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, Pioneer]] service: pioneer service name or instance
        :return: dict
        {
            "CMD": "StartULtraffic",
            "EQIndex": 1, # {-1, 1~n}, -1 means all UEs, 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        eqindex = int(eqindex)
        port = str(port)
        testtime = str(testtime)
        bandwidth = int(bandwidth)
        buffersize = int(buffersize)
        packetsize = int(packetsize)
        return service.StartULtraffic(eqindex, protocol, address, port, testtime, bandwidth, buffersize, packetsize,
                                      until_timeout=until_timeout).dictionary

    @lookup_handler.implicit_lookup
    def startcompositetestplan(self, eqindex, tests,
                               until_timeout=None, service=None):
        """
        execute StartCompositeTestPlan to start Up an Down Link Traffic

        :param int eqindex: UE index, -1 means all UEs, starts from 1 for single specific UE
        :param list[dict] tests: tests paramters.
         test parameters e.g
            {
                "TestKind": "Iperf",
                "TestParam": {
                    "Protocol": "UDP",   # traffic protocol, e.g {UDP/TCP}, means default protocol UDP.
                    "Address": "8.8.8.8",# target(e.g. app server) ip address, APP server IP address.
                    "Port": "61004",     # target port NO. UNION[int, Char]，APP server port.
                    "TestTime": "1200",  # time last for traffic in second. UNION[int, Char]，Test time.
                    "Bandwidth": 204800, # bandwidth in Kbps. Optional if Protocol is TCP.
                    "BufferSize": 0,     # buffersize in KB
                    "PacketSize": 1400,  # packetsize in Byte
                    "IperfType": 0,      # iperf type, e.g 0:iperf2; 1:iperf3.Can be set 1 if Direction is 1.
                    "Direction": 0,      # traffic direction, e.g 0:UpLink; 1: DownLink.
                    "ThreadCount": 5     # tread count.
                }
            }
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, Pioneer]] service: pioneer service name or instance
        :return: dict
        {
            "CMD": "StartCompositeTestPlan",
            "EQIndex": 1, # {-1, 1~n}, -1 means all UEs, 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, return -1 if failure or abnormal.
                 "SubStates": [0] # if EQIndex is -1, return all UE’s’ result. return 0
                                  # if success, otherwise return the error codes.

            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        eqindex = int(eqindex)
        return service.startcompositetestplan(eqindex, tests,
                                              until_timeout=until_timeout).dictionary

